export function getProductsByCategory(categorySlug) {
  return products.filter((p) => p.categories && p.categories.includes(categorySlug));
}

export function getProductsBySubcategory(categorySlug, subcategorySlug) {
  return products.filter(
    (p) => p.categories && p.categories.includes(categorySlug) && p.subcategories && p.subcategories.includes(subcategorySlug)
  );
}

export function getRelatedProducts(productSlug, limit = 4) {
  const product = products.find((p) => p.slug === productSlug);
  if (!product) return [];
  const primaryCat = product.categories?.[0];
  return products
    .filter((p) => p.slug !== productSlug && p.categories?.includes(primaryCat))
    .slice(0, limit);
}

export function getAllCategories() {
  const cats = new Set();
  products.forEach(p => {
    if (p.categories) p.categories.forEach(c => cats.add(c));
  });
  return Array.from(cats);
}

export function getAllSubcategories(categorySlug) {
  const subcats = new Set();
  products
    .filter(p => p.categories && p.categories.includes(categorySlug))
    .forEach(p => {
      if (p.subcategories) p.subcategories.forEach(s => subcats.add(s));
    });
  return Array.from(subcats);
}

export function getProductBySlug(slug) {
  return products.find((p) => p.slug === slug);
}
